import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const m=JSON.parse('{"title":"公交车司机求职邮件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/emails/09-bus-driver-job-application.md","filePath":"zh/more/maltese/practice/emails/09-bus-driver-job-application.md"}'),e={name:"zh/more/maltese/practice/emails/09-bus-driver-job-application.md"},o=r('<h1 id="公交车司机求职邮件" tabindex="-1">公交车司机求职邮件 <a class="header-anchor" href="#公交车司机求职邮件" aria-label="Permalink to &quot;公交车司机求职邮件&quot;">​</a></h1><p><strong>场景：</strong> 申请人写信给公交公司，申请公交车司机职位。</p><h2 id="邮件头部" tabindex="-1">邮件头部 <a class="header-anchor" href="#邮件头部" aria-label="Permalink to &quot;邮件头部&quot;">​</a></h2><p><strong>Lil（收件人 To）：</strong> <a href="mailto:info@transport.com" target="_blank" rel="noreferrer">info@transport.com</a><strong>Mingħand（发件人 From）：</strong> [isem]@email.com <strong>Data（日期）：</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett（主题）：</strong> Applikazzjoni ta&#39; xogħol ta&#39; sewwieq tal-karozza tal-linja</p><h2 id="邮件全文" tabindex="-1">邮件全文 <a class="header-anchor" href="#邮件全文" aria-label="Permalink to &quot;邮件全文&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:info@transport.com" target="_blank" rel="noreferrer">info@transport.com</a><strong>Mingħand:</strong> [isem]@email.com <strong>Data:</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Applikazzjoni ta&#39; xogħol ta&#39; sewwieq tal-karozza tal-linja</p><p>Għażiż Sinjur / Sinjura,</p><p>Qed nikteb biex napplika għall-impjieg ta&#39; sewwieq tal-karozza tal-linja.</p><p>Għandi liċenzja tas-sewqan tal-kategorija D.</p><p>Għandi esperjenza ta&#39; tliet snin bħala sewwieq tal-karozza tal-linja.</p><p>Naf it-toroq ta&#39; Malta tajjeb ħafna.</p><p>Jien responsabbli u jimpurtani mis-sigurtà tal-passiġġieri.</p><p>Ninsab kalm u paċenzjuż mat-traffiku.</p><p>Nirrispetta r-regoli tat-triq u nżomm il-ħin.</p><p>Nispera li nisma&#39; mingħandkom dalwaqt.</p><p>Grazzi talli qiesu l-applikazzjoni tiegħi.</p><p>Tislijiet, [Ismek]</p></blockquote><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:info@transport.com" target="_blank" rel="noreferrer">info@transport.com</a></p><p><strong>整句：</strong> 收件人（To）：info@transport.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Lil</td><td>收件人；给……</td><td>邮件头部&quot;To&quot;的马耳他语标签</td></tr><tr><td><a href="mailto:info@transport.com" target="_blank" rel="noreferrer">info@transport.com</a></td><td>邮箱地址</td><td>公交公司的招聘邮箱（示例）</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: [isem]@email.com</p><p><strong>整句：</strong> 发件人（From）：[你的名字]@email.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Mingħand</td><td>发件人；来自……</td><td>邮件头部&quot;From&quot;的马耳他语标签，本义&quot;从……那里&quot;</td></tr><tr><td>[isem]@email.com</td><td>邮箱地址</td><td>你的邮箱占位，请替换为真实邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Data: 15 ta&#39; Ottubru 2026</p><p><strong>整句：</strong> 日期：2026 年 10 月 15 日</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Data</td><td>日期</td><td>邮件头部&quot;Date&quot;；马耳他语日期格式为&quot;日 ta&#39; 月 年&quot;</td></tr><tr><td>15</td><td>十五</td><td>日期中的日</td></tr><tr><td>ta&#39;</td><td>……的</td><td>连接日和月份</td></tr><tr><td>Ottubru</td><td>十月</td><td>月份名</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Applikazzjoni ta&#39; xogħol ta&#39; sewwieq tal-karozza tal-linja</p><p><strong>整句：</strong> 主题：公交车司机职位申请</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Suġġett</td><td>主题</td><td>邮件头部&quot;Subject&quot;</td></tr><tr><td>Applikazzjoni</td><td>申请</td><td>阴性名词，借词 application</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>xogħol</td><td>工作；职位</td><td>阳性名词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>sewwieq</td><td>司机</td><td>阳性名词</td></tr><tr><td>tal-karozza</td><td>汽车的</td><td><code>ta&#39;</code> + <code>il-karozza</code> 缩合</td></tr><tr><td>tal-linja</td><td>线路的</td><td><code>ta&#39;</code> + <code>il-linja</code> 缩合；合起来即“公交车”</td></tr></tbody></table><p><strong>Malti:</strong> Għażiż Sinjur / Sinjura,</p><p><strong>整句：</strong> 亲爱的先生 / 女士：</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għażiż</td><td>亲爱的</td><td>阳性单数形式</td></tr><tr><td>Sinjur</td><td>先生</td><td>阳性名词</td></tr><tr><td>/</td><td>或</td><td>表示二选一</td></tr><tr><td>Sinjura</td><td>女士</td><td>阴性名词</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Qed nikteb biex napplika għall-impjieg ta&#39; sewwieq tal-karozza tal-linja.</p><p><strong>整句：</strong> 我写信是为了申请公交车司机职位。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Qed</td><td>正在（进行时标记）</td><td>与动词连用表示正在做某事</td></tr><tr><td>nikteb</td><td>我写</td><td>第一人称单数现在时</td></tr><tr><td>biex</td><td>为了</td><td>引出目的状语</td></tr><tr><td>napplika</td><td>我申请</td><td>第一人称单数形式，借词 apply</td></tr><tr><td>għall-impjieg</td><td>申请职位</td><td><code>għal</code> + <code>l-impjieg</code> 缩合</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>sewwieq</td><td>司机</td><td>阳性名词</td></tr><tr><td>tal-karozza</td><td>汽车的</td><td><code>ta&#39;</code> + <code>il-karozza</code> 缩合</td></tr><tr><td>tal-linja</td><td>线路的</td><td><code>ta&#39;</code> + <code>il-linja</code> 缩合；合起来即“公交车”</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Għandi liċenzja tas-sewqan tal-kategorija D.</p><p><strong>整句：</strong> 我持有 D 类驾驶执照。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għandi</td><td>我有</td><td><code>għand</code> 的第一人称单数形式</td></tr><tr><td>liċenzja</td><td>执照</td><td>阴性名词，借词 licence</td></tr><tr><td>tas-sewqan</td><td>驾驶的</td><td><code>ta&#39;</code> + <code>is-sewqan</code>“驾驶”缩合</td></tr><tr><td>tal-kategorija</td><td>类别的</td><td><code>ta&#39;</code> + <code>il-kategorija</code> 缩合</td></tr><tr><td>D</td><td>D（类）</td><td>指大型客车驾驶类别</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Għandi esperjenza ta&#39; tliet snin bħala sewwieq tal-karozza tal-linja.</p><p><strong>整句：</strong> 我有三年公交车司机的经验。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għandi</td><td>我有</td><td><code>għand</code> 的第一人称单数形式</td></tr><tr><td>esperjenza</td><td>经验</td><td>阴性名词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>tliet</td><td>三</td><td>数词，后接复数名词</td></tr><tr><td>snin</td><td>年</td><td><code>sena</code> 的复数形式</td></tr><tr><td>bħala</td><td>作为</td><td>介词</td></tr><tr><td>sewwieq</td><td>司机</td><td>阳性名词</td></tr><tr><td>tal-karozza tal-linja</td><td>公交车的</td><td>同上，“线路的车”</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Naf it-toroq ta&#39; Malta tajjeb ħafna.</p><p><strong>整句：</strong> 我对马耳他的道路非常熟悉。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Naf</td><td>我知道；我熟悉</td><td>第一人称单数形式</td></tr><tr><td>it-toroq</td><td>道路</td><td><code>triq</code>“路”的复数形式，带定冠词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>Malta</td><td>马耳他</td><td>地名</td></tr><tr><td>tajjeb</td><td>好</td><td>此处作副词“很好地”</td></tr><tr><td>ħafna</td><td>非常</td><td>程度副词</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Jien responsabbli u jimpurtani mis-sigurtà tal-passiġġieri.</p><p><strong>整句：</strong> 我负责任，并且在意乘客的安全。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jien</td><td>我</td><td>第一人称单数代词</td></tr><tr><td>responsabbli</td><td>负责任的</td><td>形容词，借词 responsible</td></tr><tr><td>u</td><td>并且</td><td>连词</td></tr><tr><td>jimpurtani</td><td>我在意</td><td><code>jimpurta</code> + <code>-ni</code>“我”，惯用表达</td></tr><tr><td>mis-sigurtà</td><td>关于安全</td><td><code>minn</code> + <code>is-sigurtà</code> 缩合</td></tr><tr><td>tal-passiġġieri</td><td>乘客的</td><td><code>ta&#39;</code> + <code>il-passiġġieri</code>（复数）缩合</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Ninsab kalm u paċenzjuż mat-traffiku.</p><p><strong>整句：</strong> 面对交通，我保持冷静和耐心。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Ninsab</td><td>我处于；我保持</td><td>第一人称单数形式</td></tr><tr><td>kalm</td><td>冷静的</td><td>形容词</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>paċenzjuż</td><td>有耐心的</td><td>形容词</td></tr><tr><td>mat-traffiku</td><td>面对交通</td><td><code>ma&#39;</code> + <code>it-traffiku</code> 缩合</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Nirrispetta r-regoli tat-triq u nżomm il-ħin.</p><p><strong>整句：</strong> 我遵守交通规则，并且守时。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nirrispetta</td><td>我尊重；我遵守</td><td>第一人称单数形式，借词 respect</td></tr><tr><td>r-regoli</td><td>规则</td><td><code>regola</code> 的复数，带定冠词</td></tr><tr><td>tat-triq</td><td>道路的</td><td><code>ta&#39;</code> + <code>it-triq</code> 缩合；即“交通规则”</td></tr><tr><td>u</td><td>并且</td><td>连词</td></tr><tr><td>nżomm</td><td>我保持；我遵守</td><td>第一人称单数形式</td></tr><tr><td>il-ħin</td><td>时间</td><td><code>nżomm il-ħin</code> 固定表达“守时”</td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li nisma&#39; mingħandkom dalwaqt.</p><p><strong>整句：</strong> 我希望很快收到你们的回复。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nispera</td><td>我希望</td><td>第一人称单数形式</td></tr><tr><td>li</td><td>……；引出从句</td><td>连词</td></tr><tr><td>nisma&#39;</td><td>我听到；收到消息</td><td>第一人称单数形式</td></tr><tr><td>mingħandkom</td><td>从你们那里</td><td><code>mingħand</code> + <code>-kom</code>“你们”</td></tr><tr><td>dalwaqt</td><td>很快</td><td>副词</td></tr></tbody></table><h3 id="_9" tabindex="-1">9. <a class="header-anchor" href="#_9" aria-label="Permalink to &quot;9.&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi talli qiesu l-applikazzjoni tiegħi.</p><p><strong>整句：</strong> 感谢你们考虑我的申请。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Grazzi</td><td>谢谢</td><td>礼貌用语</td></tr><tr><td>talli</td><td>因为（你们）……</td><td>引出原因的书面表达</td></tr><tr><td>qiesu</td><td>他们考虑了</td><td><code>qies</code> 的第三人称复数过去时</td></tr><tr><td>l-applikazzjoni</td><td>申请</td><td>阴性名词，带定冠词</td></tr><tr><td>tiegħi</td><td>我的</td><td>所有格代词</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, [Ismek]</p><p><strong>整句：</strong> 此致敬意，[你的名字]（正式邮件落款）。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tislijiet</td><td>此致敬意；致以问候</td><td>正式邮件/信件落款用语，本义&quot;问候/致意&quot;</td></tr><tr><td>Ismek</td><td>你的名字</td><td><code>isem</code>“名字” + <code>-ek</code>“你的”；请替换为真实姓名</td></tr></tbody></table>',61),i=[o];function n(l,s,h,p,c,b){return d(),a("div",null,i)}const u=t(e,[["render",n]]);export{m as __pageData,u as default};
